import { JsonPatch } from 'cdk8s';
import * as k8s from './imports/k8s';

// The classes generated by `cdk8s import` apply JSON patches before their
// toJson_* conversion, which drops plain values for IntOrString and Quantity
// fields (`maxSurge: '50%'`, `cpu: '2'`) and crashes on `null`
// (https://github.com/cdk8s-team/cdk8s/issues/2172). These subclasses keep the
// patches back and apply them to the converted manifest, as the cdk8s escape
// hatch docs describe.

/**
 * KubeDeployment that applies JSON patches after the toJson conversion.
 */
export class PloneKubeDeployment extends k8s.KubeDeployment {
  private readonly rawPatches: JsonPatch[] = [];

  public addJsonPatch(...ops: JsonPatch[]): void {
    this.rawPatches.push(...ops);
  }

  public toJson(): any {
    return JsonPatch.apply(super.toJson(), ...this.rawPatches);
  }
}

/**
 * KubeService that applies JSON patches after the toJson conversion.
 */
export class PloneKubeService extends k8s.KubeService {
  private readonly rawPatches: JsonPatch[] = [];

  public addJsonPatch(...ops: JsonPatch[]): void {
    this.rawPatches.push(...ops);
  }

  public toJson(): any {
    return JsonPatch.apply(super.toJson(), ...this.rawPatches);
  }
}

/**
 * Converts a value for a raw JSON patch: cdk8s value objects such as
 * IntOrString and Quantity (from these imports or from cdk8s-plus) become
 * their plain value, recursively. Plain values pass through unchanged.
 */
export function toManifestValue(value: any): any {
  if (Array.isArray(value)) {
    return value.map(toManifestValue);
  }
  if (value !== null && typeof value === 'object') {
    if (Object.getPrototypeOf(value) !== Object.prototype && 'value' in value) {
      return value.value;
    }
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, toManifestValue(v)]));
  }
  return value;
}
